import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int value;
        List<Node> children;

        Node(int value) {
            this.value = value;
            this.children = new ArrayList<>();
        }
    }

    static class NaryTree {
        Node root;
        Map<Integer, Node> nodeMap;

        NaryTree() {
            nodeMap = new HashMap<>();
        }

        void insert(int parentValue, int value) {
            Node parent = nodeMap.get(parentValue);
            if (parent == null) {
                parent = new Node(parentValue);
                nodeMap.put(parentValue, parent);
                if (root == null) {
                    root = parent;
                }
            }

            Node child = new Node(value);
            parent.children.add(child);
            nodeMap.put(value, child);
        }

        void delete(int value) {
            Node node = nodeMap.get(value);
            if (node == null) return;

            // Find parent and remove reference to this node
            if (node == root) {
                root = null;
            } else {
                for (Map.Entry<Integer, Node> entry : nodeMap.entrySet()) {
                    Node n = entry.getValue();
                    if (n.children.contains(node)) {
                        n.children.remove(node);
                        break;
                    }
                }
            }

            // Remove all descendants
            removeDescendants(node);
            nodeMap.remove(value);
        }

        private void removeDescendants(Node node) {
            for (Node child : node.children) {
                removeDescendants(child);
                nodeMap.remove(child.value);
            }
            node.children.clear();
        }

        List<Integer> preorder() {
            List<Integer> result = new ArrayList<>();
            preorderHelper(root, result);
            return result;
        }

        private void preorderHelper(Node node, List<Integer> result) {
            if (node == null) return;
            result.add(node.value);
            for (Node child : node.children) {
                preorderHelper(child, result);
            }
        }

        List<Integer> postorder() {
            List<Integer> result = new ArrayList<>();
            postorderHelper(root, result);
            return result;
        }

        private void postorderHelper(Node node, List<Integer> result) {
            if (node == null) return;
            for (Node child : node.children) {
                postorderHelper(child, result);
            }
            result.add(node.value);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        sc.nextLine(); // consume newline

        NaryTree tree = new NaryTree();

        for (int i = 0; i < n; i++) {
            String line = sc.nextLine().trim();
            String[] parts = line.split("\\s+");

            if (parts[0].equals("insert")) {
                int parentValue = Integer.parseInt(parts[1]);
                int value = Integer.parseInt(parts[2]);
                tree.insert(parentValue, value);
            } else if (parts[0].equals("delete")) {
                int value = Integer.parseInt(parts[1]);
                tree.delete(value);
            } else if (parts[0].equals("preorder")) {
                List<Integer> result = tree.preorder();
                System.out.println(String.join(" ", result.stream().map(String::valueOf).toArray(String[]::new)));
            } else if (parts[0].equals("postorder")) {
                List<Integer> result = tree.postorder();
                System.out.println(String.join(" ", result.stream().map(String::valueOf).toArray(String[]::new)));
            }
        }

        sc.close();
    }
}
